def form_body(lang):
    c = F[lang]; f = c["f"]; U = P.U()
    rows = "".join(f'<div><dt>{H(a)}</dt><dd>' + (f'<a href="{URLS["privacidad"][IDX[lang]]}">{H(c["more"])}</a>' if b is None else H(b)) + '</dd></div>' for a, b in c["l1rows"])
    jsd = f'data-min="{H(c["js"]["min"])}" data-max="{H(c["js"]["max"])}" data-okc="{H(c["js"]["okc"])}" data-err-desc="{H(c["js"]["errDesc"])}" data-err-gen="{H(c["js"]["errGen"])}"'
    form = f'''<form class="form" id="pre-form" name="preinscripcion" method="POST" action="{URLS["gracias"][IDX[lang]]}" data-netlify="true" netlify-honeypot="bot-field" data-open="{OPEN}" {jsd}>
<input type="hidden" name="form-name" value="preinscripcion"><input type="hidden" name="lang" value="{lang}"><input type="hidden" name="consent_version" value="{CONSENT_VERSION}">
<p class="hp" aria-hidden="true"><label>{H(c["hp"])} <input name="bot-field" tabindex="-1" autocomplete="off"></label></p>
<p id="closed" class="closed" role="status" hidden>{H(c["closed"])}</p>
<fieldset style="border:0;padding:0;margin:0;display:grid;gap:var(--s4)">
<div class="fld"><label for="nombre">{H(f["name"])}</label><input type="text" id="nombre" name="nombre" required minlength="2" maxlength="120" autocomplete="name"></div>
<div class="fld"><label for="email">{H(f["email"])}</label><input type="email" id="email" name="email" required maxlength="254" autocomplete="email" inputmode="email"></div>
<div class="fld"><label for="pais">{H(f["country"])}</label><input type="text" id="pais" name="pais" required minlength="2" maxlength="80" autocomplete="country-name"></div>
<div class="fld"><label for="descripcion">{H(f["desc"])}</label><textarea id="descripcion" name="descripcion" required minlength="300" maxlength="600" aria-describedby="dhint cnt"></textarea><span class="hint" id="dhint">{H(f["desc_hint"])}</span><span class="cnt mono" id="cnt" aria-live="off"></span></div>
<div class="fld"><label for="experiencia">{H(f["exp"])} <span class="opt">{H(f["opt"])}</span></label><textarea id="experiencia" name="experiencia" maxlength="600" style="min-height:6rem" aria-describedby="ehint"></textarea><span class="hint" id="ehint">{H(f["exp_hint"])}</span></div>
<label class="chk"><input type="checkbox" name="privacidad" required><span>{c["c1"]}</span></label>
<label class="chk"><input type="checkbox" name="novedades"><span>{H(c["c2"])}</span></label>
<button class="cta" type="submit">{H(f["send"])}</button>
</fieldset>
<p class="visually-hidden" id="form-live" role="alert"></p>
</form>'''
    layer = f'<aside class="layer1" aria-labelledby="l1"><h2 class="h2s" id="l1">{H(c["l1"])}</h2><dl class="ficha">{rows}</dl></aside>'
    return sec(f'<p>{c["steps"]}</p>' + form + layer)

