def legal_page(lang, which, key):
    P.LANG = lang; d = LEGAL[lang][which]
    body = '<section><div class="wrap prose legal-doc">' + "".join(f"<h2>{H(h)}</h2>" + "".join(p if p.startswith("<ul") else f"<p>{p}</p>" for p in ps) for h, ps in d["s"]) + "</div></section>"
    write(URLS[key][IDX[lang]], page(key, d["title"], d["desc"], d["kicker"], d["h1"], d["lead"], body))

def with_js(s): return s.replace("</body>", '<script src="/assets/form.v1.js" defer></script>\n</body>')

def simple_page(lang, key, h1, lead, para, with_mail=True):
    c = F[lang]
    body = sec(f'<p>{H(para)} {MAIL if with_mail else ""}</p><p style="margin-top:var(--s4)"><a class="cta" href="{URLS["home"][IDX[lang]]}">{H(c["back"])}</a></p>')
    write(URLS[key][IDX[lang]], page(key, h1.replace("<br>", " ") + " · Ultra Trail Larre®", lead, c["kicker"], h1, lead, body, noindex=True))

if __name__ == "__main__":
    for lang in ("es", "en", "eu"):
        P.LANG = lang; c = F[lang]
        write(URLS["preinscripcion"][IDX[lang]], with_js(page("preinscripcion", c["title"], c["desc"], c["kicker"], c["h1"], c["lead"], form_body(lang))))
        simple_page(lang, "gracias", c["thanks_h1"], c["thanks_lead"], c["thanks_p"])
        simple_page(lang, "confirmado", c["conf_h1"], c["conf_lead"], c["conf_p"])
        legal_page(lang, "aviso", "aviso"); legal_page(lang, "priv", "privacidad")
    print("formularios y textos legales generados")
